// === Tab: mySketch ===
var circles = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(255);
}

function draw() {
	circles.push(new Circle(80, color(255)));

  if(circles.length != 0) {
    for(let i = 0; i < circles.length; i++) {
      var c = circles[i];
      c.show();
      c.move();

      if(c.isDead()) circles.splice(i, 1);
    }
  }
}

class Circle {
  constructor(s_, c_) {
    this.pos = createVector(width/2, height/2);
    this.vel = createVector();
    this.acel = createVector();
    this.s = s_;
    this.c = c_;
  }

  move() {
    this.acel = p5.Vector.random2D();
    this.vel.add(this.acel.mult(0.5));
    this.vel.limit(5);
    this.pos.add(this.vel);
    this.s--;
  }

  show() {
    fill(this.c);
    stroke(2);
    stroke(0);
    ellipse(this.pos.x, this.pos.y, this.s, this.s);
  }

  isDead() {
    if(this.s < 1) return true;
    else return false;
  }
}

